// Estes dados foram criados exclusivamente para demonstração.
const vaga = { titulo: 'Atendimento empresarial', criterios: ['atendimento', 'organização', 'relatórios'] };
const perfis = [
  { id: 'Exemplo A', experiencia: 'Atendimento a empresas e organização de solicitações.' },
  { id: 'Exemplo B', experiencia: 'Produção de relatórios e acompanhamento de processos.' },
];
return perfis.map(perfil => ({ json: { vaga, perfil } }));

return $input.all().map(({ json }) => {
  const { vaga, perfil } = json;
  const texto = perfil.experiencia.toLocaleLowerCase('pt-BR');
  const evidencias = vaga.criterios.filter(criterio => texto.includes(criterio));
  const naoIdentificado = vaga.criterios.filter(criterio => !texto.includes(criterio));
  return { json: { perfil: perfil.id, evidencias, naoIdentificado, pedidoParaIA: { instrucao: 'Organize as evidências e lacunas para revisão humana. Não infira informações ausentes e não tome decisão de contratação.', vaga, perfil } } };
});
